DO $$
BEGIN
    IF EXISTS (
        WITH candidate_matches AS (
            SELECT
                seed.title_ru,
                COUNT(DISTINCT p.id) AS match_count
            FROM seed_vietnam_visit_planning seed
            LEFT JOIN place_translations pt
              ON pt.locale = 'ru'
             AND pt.title = seed.title_ru
            LEFT JOIN places p
              ON p.id = pt.place_id
             AND p.country_code = 'VN'
             AND p.deleted_at IS NULL
             AND p.source = 'IMPORT'
            GROUP BY seed.title_ru
        )
        SELECT 1
        FROM candidate_matches
        WHERE match_count <> 1
    ) THEN
        RAISE EXCEPTION 'Vietnam visit-planning seed has missing or ambiguous place matches';
    END IF;
END $$;

WITH matched_places AS (
    SELECT DISTINCT
        p.id AS place_id,
        seed.price_amount,
        seed.visit_info
    FROM seed_vietnam_visit_planning seed
    JOIN place_translations pt
      ON pt.locale = 'ru'
     AND pt.title = seed.title_ru
    JOIN places p
      ON p.id = pt.place_id
     AND p.country_code = 'VN'
     AND p.deleted_at IS NULL
     AND p.source = 'IMPORT'
)
DELETE FROM place_fee_items f
USING matched_places m
WHERE f.place_id = m.place_id;

WITH matched_places AS (
    SELECT DISTINCT
        p.id AS place_id,
        seed.price_amount,
        seed.visit_info
    FROM seed_vietnam_visit_planning seed
    JOIN place_translations pt
      ON pt.locale = 'ru'
     AND pt.title = seed.title_ru
    JOIN places p
      ON p.id = pt.place_id
     AND p.country_code = 'VN'
     AND p.deleted_at IS NULL
     AND p.source = 'IMPORT'
)
DELETE FROM place_access_options a
USING matched_places m
WHERE a.place_id = m.place_id;

WITH matched_places AS (
    SELECT DISTINCT
        p.id AS place_id,
        seed.price_amount,
        seed.visit_info
    FROM seed_vietnam_visit_planning seed
    JOIN place_translations pt
      ON pt.locale = 'ru'
     AND pt.title = seed.title_ru
    JOIN places p
      ON p.id = pt.place_id
     AND p.country_code = 'VN'
     AND p.deleted_at IS NULL
     AND p.source = 'IMPORT'
)
DELETE FROM place_practical_notes pn
USING matched_places m
WHERE pn.place_id = m.place_id;

WITH matched_places AS (
    SELECT DISTINCT
        p.id AS place_id,
        seed.price_amount,
        seed.visit_info
    FROM seed_vietnam_visit_planning seed
    JOIN place_translations pt
      ON pt.locale = 'ru'
     AND pt.title = seed.title_ru
    JOIN places p
      ON p.id = pt.place_id
     AND p.country_code = 'VN'
     AND p.deleted_at IS NULL
     AND p.source = 'IMPORT'
)
DELETE FROM place_recommended_items ri
USING matched_places m
WHERE ri.place_id = m.place_id;

WITH matched_places AS (
    SELECT DISTINCT
        p.id AS place_id,
        seed.price_amount,
        seed.visit_info
    FROM seed_vietnam_visit_planning seed
    JOIN place_translations pt
      ON pt.locale = 'ru'
     AND pt.title = seed.title_ru
    JOIN places p
      ON p.id = pt.place_id
     AND p.country_code = 'VN'
     AND p.deleted_at IS NULL
     AND p.source = 'IMPORT'
)
UPDATE places p
SET
    price_amount = COALESCE(m.price_amount, p.price_amount),
    price_currency = CASE WHEN m.price_amount IS NULL THEN p.price_currency ELSE 'VND' END,
    visit_info = jsonb_strip_nulls(
        COALESCE(p.visit_info, '{}'::jsonb)
        || m.visit_info
        || jsonb_build_object('lastVerifiedAt', '2026-06-28')
    ),
    updated_at = NOW()
FROM matched_places m
WHERE p.id = m.place_id;

WITH matched_places AS (
    SELECT DISTINCT
        p.id AS place_id,
        seed.price_amount,
        seed.visit_info
    FROM seed_vietnam_visit_planning seed
    JOIN place_translations pt
      ON pt.locale = 'ru'
     AND pt.title = seed.title_ru
    JOIN places p
      ON p.id = pt.place_id
     AND p.country_code = 'VN'
     AND p.deleted_at IS NULL
     AND p.source = 'IMPORT'
